import { useMutation, UseMutationOptions } from '@tanstack/react-query';
import axios from 'axios';
import { AccountCheckRequest } from '~/entities/pin/api/dtos/types';
import { AccountValidResponseDTO } from '~/entities/wallet/api/dtos/account-valid';
import { CBDCAxiosError } from '~/shared/@types/error';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

export const accountCheck = (req: AccountCheckRequest) => {
  return resultify(axios.post<AccountValidResponseDTO>(`${API_URLS.getCommonUrl('acnut')}`, req));
};

export const useAccountCheckMutation = (
  options?: UseMutationOptions<AccountValidResponseDTO, CBDCAxiosError, AccountCheckRequest>,
) => {
  const mutation = useMutation<AccountValidResponseDTO, CBDCAxiosError, AccountCheckRequest>({
    ...options,
    mutationFn: (req: AccountCheckRequest) => accountCheck(req),
  });

  return {
    ...mutation,
  };
};
